  reg  [1:0]  state;
  reg         saved_req_valid;
  reg  [31:0] saved_req_bits_addr;
  reg         saved_req_bits_write;
  reg  [31:0] saved_req_bits_wdata;
  reg  [3:0]  saved_req_bits_wstrb;
