                                    & io_src_info_src1_data < io_src_info_src2_data
                                  : _GEN_7 & io_info_valid & _io_branch_T_30
                                    & io_src_info_src1_data >= io_src_info_src2_data;
  assign io_target =
    _GEN
      ? io_pc + io_info_imm
      : _GEN_0
          ? io_pc + io_info_imm
          : _GEN_1
              ? io_src_info_src1_data + io_info_imm
              : _GEN_2
                  ? io_pc + io_info_imm
                  : _GEN_3
                      ? io_pc + io_info_imm
                      : _GEN_4
